+    outline: none;
+  }
+`;
+
+interface EstimateItem {
+  name: string;
+  price: string;
+  description: string;
+  fe: string; // 프론트엔드 개발 여부
+  be: string; // 백엔드 개발 여부
+  page_count: number; // 페이지 수
+  is_deleted: boolean;
+  item_id?: string;  // 옵셔널로 변경
+}
+
+// 할인 제외 항목명
+const NON_DISCOUNT_ITEMS = ['화면설계', '화면디자인', '화면퍼블리싱', '퍼블리싱', 'UI/UX디자인','화면 설계','화면 퍼블리싱','UI/UX 디자인','스토리보드', '스토리 보드', '서비스 기획'];
+
+
+interface EstimateAccordionItemProps {
+  name: string;
+  price?: string;
+  description?: string;
+  items?: EstimateItem[];
+  depth: 1 | 2 | 3;
+  onItemClick?: (item: EstimateItem) => void;
+  onItemDelete?: (itemId: string, item: EstimateItem) => void;
+  onItemRestore?: (itemId: string, item: EstimateItem) => void;
+  children?: React.ReactNode;
+  isSelected?: boolean;
+  onSelect?: () => void;
+  selectedItemId?: string | null;
+  onItemSelect?: (itemId: string) => void;
+  chatRoomId?: string;
+  estimateId?: string;
+  discountRate?: number; // 0~1, 0.1이면 10% 할인 (기존 호환성)
+  periodValue?: number; // 연장 기간 값 (주, 월, 수량)
+  discountSettings?: DiscountSettings; // 할인 설정
+  isOpen?: boolean; // 외부에서 제어되는 열림/닫힘 상태
+}
+
+const EstimateAccordionItem: React.FC<EstimateAccordionItemProps> = ({
+  name,
+  price,
+  items = [],
+  depth,
+  onItemClick,
+  onItemDelete,
+  onItemRestore,
+  children,
+  isSelected = false,
